sparql:
SELECT DISTINCT ?ProvidedCHO
WHERE { ?ProvidedCHO rdf:type edm:ProvidedCHO }
LIMIT 10

SELECT ?Proxy
WHERE {
  ?Proxy rdf:type ore:Proxy ;
         edm:europeanaProxy "false"
}

SELECT ?Proxy
WHERE {
  ?EuropeanaAggregation rdf:type edm:EuropeanaAggregation .
  ?Proxy ore:proxyIn ?EuropeanaAggregation
}

SELECT DISTINCT ?WebResource
WHERE { 
  ?Aggregation edm:isShownBy|edm:hasView ?WebResource ;
               edm:aggregatedCHO <http://data.europeana.eu/item/08501/Athena_Update_ProvidedCHO_Bildarchiv_Foto_Marburg_obj_00023128_LA_2_088_40> 
}

SELECT ?EuropeanaType (count(*) as ?count) 
WHERE {
  ?Aggregation edm:isShownBy|edm:hasView ?WebResource .
  ?Proxy ore:proxyIn ?Aggregation ;
         edm:type ?EuropeanaType . 
}
GROUP BY ?EuropeanaType

SELECT ?Rights (count(*) as ?count) 
WHERE {
  ?Aggregation edm:rights ?Rights ;
               edm:isShownBy|edm:hasView ?WebResource
}
GROUP BY ?Rights
ORDER BY DESC (?count)

SELECT DISTINCT ?WebResource ?ProvidedCHO
WHERE { 
  ?Aggregation edm:rights ?Rights ;
               edm:isShownBy|edm:hasView ?WebResource ;
               edm:aggregatedCHO ?ProvidedCHO .
  ?Proxy ore:proxyIn ?Aggregation ;
         edm:type "VIDEO" . 
  FILTER (?Rights IN ( <http://creativecommons.org/publicdomain/mark/1.0/>
                     , <http://creativecommons.org/publicdomain/zero/1.0/>
                     , <http://creativecommons.org/licenses/by/1.0/> 
                     , <http://creativecommons.org/licenses/by-sa/1.0/> ))
}

SELECT DISTINCT ?Agent
WHERE { ?Agent rdf:type edm:Agent }
LIMIT 10

SELECT DISTINCT ?Agent
WHERE {
  ?Agent rdf:type edm:Agent .
  FILTER strstarts(str(?Agent), "http://viaf.org/viaf/")
}
LIMIT 10

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Place rdf:type edm:Agent .
  ?Proxy ?property ?Agent ;
         ore:proxyFor ?ProvidedCHO
}
LIMIT 10

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Proxy dc:creator|dc:contributor ?Agent ;
         ore:proxyFor ?ProvidedCHO
}
LIMIT 10

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Proxy ?property ?Agent ;
         ore:proxyFor ?ProvidedCHO .
  ?Agent rdf:type edm:Agent .
  FILTER strstarts(str(?Agent), "http://viaf.org/viaf/")
}
LIMIT 10

SELECT DISTINCT ?Place
WHERE {
  ?Place rdf:type edm:Place .
  FILTER strstarts(str(?Place), "http://sws.geonames.org/")
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Place rdf:type edm:Place .
  ?Proxy ?property ?Place ;
         ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Place rdf:type edm:Place .
  ?Proxy dcterms:spatial|dc:coverage ?Place ;
         ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Place rdf:type edm:Place .
  FILTER strstarts(str(?Place), "http://sws.geonames.org/")
  ?Proxy ?property ?Place ; 
         ore:proxyFor ?ProvidedCHO
}

SELECT ?Place (count(DISTINCT ?property) as ?count)
WHERE {
  ?Place rdf:type edm:Place ;
         ?property ?value .
}
GROUP BY ?Place 
ORDER BY DESC(?count)

SELECT DISTINCT ?Concept
WHERE {
  ?Concept rdf:type skos:Concept .
  FILTER strstarts(str(?Concept), "http://vocab.getty.edu/aat/") .
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Concept rdf:type skos:Concept .
  ?Proxy ?property ?Concept ; 
         ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Proxy dc:type|dc:subject ?Concept ;
         ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Concept rdf:type skos:Concept .
  FILTER strstarts(str(?Concept), "http://vocab.getty.edu/aat/") .
  ?Proxy ?property ?Concept ;
         ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
  ?Time rdf:type edm:TimeSpan .
  ?Proxy ?property ?Time ;
         ore:proxyFor ?ProvidedCHO
}

SELECT ?ProvidedCHO ?year
WHERE {
  ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
               edm:country "France" .
  ?Proxy ore:proxyFor ?ProvidedCHO ;
         edm:year ?year .
  FILTER (?year > "1700" && ?year <= "1800")
}
ORDER BY asc(?year)

SELECT ?date (count(*) as ?count)  {
  ?proxy dc:type 'info:eu-repo/semantics/article'.
  OPTIONAL { ?proxy dcterms:issued ?issued }
  OPTIONAL { ?proxy dc:date        ?dcdate }
  bind (xsd:integer(substr(coalesce(?issued,?dcdate),1,4)) as ?date)
}
GROUP BY ?date HAVING (?count>1)
ORDER BY ?date

SELECT ?Date (COUNT(*) as ?count)
WHERE {
  ?x edm:hasType <http://vocab.getty.edu/aat/300026656> ;
     dc:date ?dat .
  bind(concat(substr(?dat,1,3),"0") as ?Date)
}
GROUP BY ?Date HAVING (?count>1)
ORDER BY ?Date

SELECT ?Provider (count(*) as ?count)
WHERE {
  ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
               edm:provider ?Provider .
}
GROUP BY ?Provider 
ORDER BY DESC(?count)

SELECT ?Provider ?DataProvider (count(*) as ?count)
WHERE {
  ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
               edm:provider ?Provider ;
               edm:dataProvider ?DataProvider
}
GROUP BY ?Provider ?DataProvider 
ORDER BY ?Provider ?DataProvider

SELECT ?Country (count(*) as ?count)
WHERE {
  ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
               edm:country ?Country .
}
GROUP BY ?Country
ORDER BY DESC(?count)

SELECT ?ProvidedCHO
WHERE {
  ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
               edm:country ?Country .
  FILTER (?Country = "netherlands")
}

SELECT ?Country ?Provider (count(*) as ?count) 
WHERE {
  ?AggregationEuropeana edm:country ?Country ;
                        edm:aggregatedCHO ?ProvidedCHO .
  ?AggregationProvider  edm:aggregatedCHO ?ProvidedCHO ;
                        rdf:type ore:Aggregation ;
                        edm:provider ?Provider. 
}
GROUP BY ?Country ?Provider 
ORDER BY ?Country ?Provider

SELECT ?Country ?EuropeanaType (count(*) as ?count)
WHERE {
  ?AggregationEuropeana edm:country ?Country ;
                        edm:aggregatedCHO ?ProvidedCHO .
  ?AggregationProvider  edm:aggregatedCHO ?ProvidedCHO ;
                        rdf:type ore:Aggregation ;
                        edm:provider ?Provider .  
  ?Proxy ore:proxyIn ?AggregationEuropeana ;
         edm:type ?EuropeanaType .
}
GROUP BY ?Country ?EuropeanaType 
ORDER BY ?Country ?EuropeanaType

SELECT ?Lang (count(*) as ?count) 
WHERE {
  ?Aggregation edm:language ?Lang ;
               edm:aggregatedCHO ?ProvidedCHO .
}
GROUP BY ?Lang
ORDER BY DESC(?count)

SELECT DISTINCT ?Dataset
WHERE {
  ?Aggregation edm:datasetName ?Dataset
}

SELECT ?Dataset
WHERE {
  ?Aggregation edm:datasetName ?Dataset ;
               edm:country "Italy"
}

SELECT DISTINCT ?Dataset
WHERE {
  ?Aggregation edm:datasetName ?Dataset .
  ?Proxy ore:proxyIn ?Aggregation ;
         edm:type "VIDEO"
}

SELECT DISTINCT ?Dataset
WHERE {
  ?Aggregation edm:datasetName ?Dataset ;
               edm:country "netherlands" .
  ?Proxy ore:proxyIn ?Aggregation ;
         edm:type "VIDEO"
}

SELECT DISTINCT ?Dataset
WHERE {
  ?Aggregation edm:datasetName ?Dataset ;
               edm:rights ?Rights .
  FILTER (?Rights IN ( <http://creativecommons.org/publicdomain/mark/1.0/>
                     , <http://creativecommons.org/publicdomain/zero/1.0/>
                     , <http://creativecommons.org/licenses/by/1.0/> 
                     , <http://creativecommons.org/licenses/by-sa/1.0/> ))
}
